css:
:root { --bleu: #17413A; --bleu-fonce: #0F2F29; --bleu-clair: #3F7A6C; --bleu-fond: #F3F8F5; --jaune: #6CC3A2; --rouille: #B5573F; --blanc: #FFFFFF; --encre: #132E29; --gris: #56685F; --ok: #2E9E5B; --alerte: #D64545; --r: 22px; }
.sw-ic { width: 1.15em; height: 1.15em; display: inline-block; vertical-align: -0.2em; flex: 0 0 auto; }
.tf-ov .sw-ic, .tf-av .sw-ic { color: var(--bleu,#17413A); }
.tf-av .sw-ic { color: rgb(255, 255, 255); width: 1.3em; height: 1.3em; }
.fi-chips .sw-ic, .bm-ico .sw-ic { color: var(--bleu,#17413A); }
:root { --sl-serif: 'Baloo 2',cursive; --sl-creme: #EAF3EE; --sl-ligne: rgba(19,46,41,.12); }
#sw-fiche .fi-grid > div { min-width: 0px; }
#sw-fiche .fi-extrait table { display: block; overflow-x: auto; max-width: 100%; }
#sw-fiche .fi-extrait { overflow-wrap: anywhere; }
#sw-fiche .fi-dip { display: inline-block; background: rgb(108, 195, 162); color: rgb(19, 46, 41); border-radius: 12px; padding: 6px 12px; font-size: 0.88rem; margin: 0px 0px 10px; }
#sw-fiche .fi-dipc { border: 2px solid rgb(108, 195, 162); }
#sw-fiche { display: none; position: fixed; inset: 0px; z-index: 9990; background: rgb(246, 250, 247); overflow-y: auto; }
#sw-fiche.on { display: block; }
.fi-bar { position: sticky; top: 0px; z-index: 3; display: flex; align-items: center; gap: 10px; padding: 10px 18px; background: rgba(255, 255, 255, 0.95); backdrop-filter: blur(6px); box-shadow: rgba(19, 46, 41, 0.08) 0px 2px 14px; }
.fi-bar button { border: 0px; background: rgb(238, 244, 240); color: rgb(19, 46, 41); border-radius: 999px; padding: 9px 16px; cursor: pointer; font-style: inherit; font-variant: inherit; font-stretch: inherit; font-size: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-weight: 700; }
.fi-bar b { flex: 1 1 0%; font-size: 0.9rem; color: rgb(19, 46, 41); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.fi-bar .fi-cta { background: rgb(108, 195, 162); color: rgb(46, 36, 21); }
.fi-hero { background: linear-gradient(135deg,var(--c),color-mix(in srgb,var(--c) 65%,#101A45)); color: rgb(255, 255, 255); padding: 46px 20px 54px; }
.fi-in { max-width: 1000px; margin: 0px auto; }
.fi-ligne { display: inline-flex; align-items: center; gap: 8px; background: rgba(255, 255, 255, 0.18); border-radius: 999px; padding: 6px 14px 6px 6px; font-weight: 800; font-size: 0.8rem; }
.fi-ligne i { width: 24px; height: 24px; border-radius: 50%; background: rgb(255, 255, 255); color: var(--c); display: flex; align-items: center; justify-content: center; font-style: normal; }
.fi-hero h1 { color: rgb(255, 255, 255); font-size: 2.3rem; line-height: 1.15; margin: 16px 0px 12px; max-width: 820px; }
.fi-hero .ac { font-size: 1.15rem; line-height: 1.55; opacity: 0.95; max-width: 760px; margin: 0px 0px 22px; }
.fi-chips { display: flex; flex-wrap: wrap; gap: 8px; margin-bottom: 24px; }
.fi-chips span { background: rgba(255, 255, 255, 0.16); border: 1px solid rgba(255, 255, 255, 0.28); border-radius: 999px; padding: 7px 14px; font-size: 0.86rem; font-weight: 700; }
.fi-btns { display: flex; flex-wrap: wrap; gap: 10px; }
.fi-btns button { border: 0px; border-radius: 999px; padding: 15px 26px; font-style: inherit; font-variant: inherit; font-stretch: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-weight: 800; font-size: 1rem; cursor: pointer; }
.fi-btns .p { background: rgb(108, 195, 162); color: rgb(46, 36, 21); }
.fi-btns .s { background: rgba(255, 255, 255, 0.16); color: rgb(255, 255, 255); border: 2px solid rgba(255, 255, 255, 0.5); }
.fi-body { max-width: 1000px; margin: -26px auto 0px; padding: 0px 16px 120px; position: relative; }
.fi-grid { display: grid; grid-template-columns: 1.55fr 1fr; gap: 18px; align-items: start; }
.fi-c { background: rgb(255, 255, 255); border-radius: 22px; padding: 24px 26px; box-shadow: rgba(19, 46, 41, 0.07) 0px 10px 30px; margin-bottom: 18px; }
.fi-c h2 { font-size: 1.35rem; margin: 0px 0px 14px; color: rgb(19, 46, 41); }
.fi-obj { list-style: none; margin: 0px; padding: 0px; display: grid; gap: 10px; }
.fi-obj li { display: flex; gap: 12px; align-items: flex-start; line-height: 1.5; }
.fi-obj li::before { content: "✓"; flex: 0 0 auto; width: 24px; height: 24px; border-radius: 50%; background: color-mix(in srgb,var(--c) 15%,#fff); color: var(--c); font-weight: 900; display: flex; align-items: center; justify-content: center; font-size: 0.8rem; margin-top: 1px; }
.fi-part { border-top: 1px solid rgb(230, 234, 246); }
.fi-part:first-of-type { border-top: 0px; }
.fi-part summary { list-style: none; cursor: pointer; display: flex; align-items: center; gap: 12px; padding: 14px 0px; font-weight: 800; color: rgb(19, 46, 41); }
.fi-part summary::-webkit-details-marker { display: none; }
.fi-part summary small { margin-left: auto; font-weight: 700; color: rgb(102, 118, 110); font-size: 0.8rem; }
.fi-part summary::before { content: "+"; width: 26px; height: 26px; border-radius: 8px; background: rgb(238, 244, 240); display: flex; align-items: center; justify-content: center; font-weight: 900; color: var(--c); }
.fi-part[open] summary::before { content: "−"; }
.fi-part ol { margin: 0px 0px 14px 38px; padding: 0px; color: rgb(54, 70, 63); line-height: 1.55; }
.fi-part li { margin-bottom: 5px; }
.fi-extrait { position: relative; max-height: 340px; overflow: hidden; font-size: 0.95rem; line-height: 1.6; color: rgb(42, 49, 88); }
.fi-extrait::after { content: ""; position: absolute; left: 0px; right: 0px; bottom: 0px; height: 120px; background: linear-gradient(transparent, rgb(255, 255, 255)); }
.fi-extrait .sw-ref { display: none; }
.fi-lock { text-align: center; margin-top: 6px; font-weight: 700; color: rgb(102, 118, 110); font-size: 0.9rem; }
.fi-meth { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
.fi-meth div { background: rgb(246, 247, 252); border-radius: 14px; padding: 13px 14px; font-size: 0.88rem; line-height: 1.45; }
.fi-meth b { display: block; color: rgb(19, 46, 41); margin-bottom: 3px; }
.fi-side .fi-c { padding: 20px 22px; }
.fi-side h3 { font-size: 1.02rem; margin: 0px 0px 8px; color: rgb(19, 46, 41); }
.fi-side p { margin: 0px 0px 6px; font-size: 0.9rem; line-height: 1.5; color: rgb(54, 70, 63); }
.fi-prix { border: 2px solid var(--c); }
.fi-prix .big { font: 700 1.25rem Georgia, serif; color: rgb(19, 46, 41); margin-bottom: 6px; }
.fi-prix button { width: 100%; border: 0px; border-radius: 999px; padding: 14px; margin-top: 10px; font-style: inherit; font-variant: inherit; font-stretch: inherit; font-size: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-weight: 800; cursor: pointer; background: rgb(108, 195, 162); color: rgb(46, 36, 21); }
.fi-ref { font-size: 0.86rem; line-height: 1.5; color: rgb(54, 70, 63); }
.fi-ref b { color: rgb(19, 46, 41); }
.fi-corr { display: flex; flex-direction: column; gap: 8px; }
.fi-corr button { text-align: left; border: 1px solid rgb(224, 235, 229); background: rgb(255, 255, 255); border-radius: 12px; padding: 10px 12px; font-style: inherit; font-variant: inherit; font-stretch: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-size: 0.88rem; font-weight: 700; color: rgb(19, 46, 41); cursor: pointer; display: flex; gap: 10px; align-items: center; }
.fi-corr button::before { content: ""; width: 12px; height: 12px; border-radius: 50%; border: 3px solid var(--c); flex: 0 0 auto; }
.fi-corr button:hover { border-color: var(--c); }
.fi-mob { display: none; }
@media (max-width: 820px){.fi-grid { grid-template-columns: 1fr; }.fi-hero { padding: 30px 16px 46px; }.fi-hero h1 { font-size: 1.65rem; }.fi-hero .ac { font-size: 1.02rem; }.fi-btns { display: none; }.fi-bar .fi-cta { display: none; }.fi-c { padding: 20px 16px; }.fi-meth { grid-template-columns: 1fr; }.fi-mob { display: flex; position: fixed; left: 0px; right: 0px; bottom: 0px; z-index: 4; gap: 8px; padding: 10px 12px calc(10px + env(safe-area-inset-bottom)); background: rgb(255, 255, 255); box-shadow: rgba(19, 46, 41, 0.15) 0px -6px 22px; }.fi-mob button { flex: 1 1 0%; border: 0px; border-radius: 999px; padding: 14px 8px; font-style: inherit; font-variant: inherit; font-stretch: inherit; font-size: inherit; line-height: inherit; font-family: inherit; font-optical-sizing: inherit; font-size-adjust: inherit; font-kerning: inherit; font-feature-settings: inherit; font-variation-settings: inherit; font-weight: 800; cursor: pointer; }.fi-mob .p { background: rgb(108, 195, 162); color: rgb(46, 36, 21); flex: 2 1 0%; }.fi-mob .s { background: rgb(238, 244, 240); color: rgb(19, 46, 41); }}
